<?php
require_once __DIR__.'/../config/auth.php';require_role('owner');$pageTitle='Kategori';$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=(string)($_POST['action']??'');try{if($action==='save'){$id=(int)($_POST['id']??0);$name=clean_text((string)($_POST['nama']??''),60);$order=(int)($_POST['urutan']??0);if($name==='')throw new RuntimeException('nama kategori wajib diisi.');if($id){$st=$pdo->prepare('UPDATE categories SET nama=?,urutan=? WHERE id=?');$st->execute([$name,$order,$id]);log_activity('update_category',$name);$message='kategori diperbarui.';}else{$st=$pdo->prepare('INSERT INTO categories (nama,urutan) VALUES (?,?)');$st->execute([$name,$order]);log_activity('create_category',$name);$message='kategori ditambahkan.';}}elseif($action==='delete'){$id=(int)$_POST['id'];$st=$pdo->prepare('DELETE FROM categories WHERE id=?');$st->execute([$id]);log_activity('delete_category','ID '.$id);$message='kategori dihapus.';}}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'kategori tidak bisa dihapus karena masih digunakan menu, atau nama sudah dipakai.';}}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM categories WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$cats=dbq('SELECT c.*,COUNT(m.id) total_menu FROM categories c LEFT JOIN menus m ON m.category_id=c.id GROUP BY c.id ORDER BY c.urutan,c.nama')->fetchAll();require __DIR__.'/../includes/admin-header.php'; ?>
<?php if($message):?><div class="flash flash-ok"><?= h($message) ?></div><?php endif;?><?php if($error):?><div class="flash flash-error"><?= h($error) ?></div><?php endif;?><div class="grid lg:grid-cols-[350px_1fr] gap-5"><section class="card p-5 h-fit"><h2 class="font-serif text-2xl"><?= $edit?'Edit kategori':'Tambah kategori' ?></h2><form method="post" class="space-y-4 mt-5"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div><label class="field-label">Nama kategori</label><input class="field" name="nama" required maxlength="60" value="<?= h($edit['nama']??'') ?>" placeholder="Contoh: Kopi"></div><div><label class="field-label">Urutan tampilan</label><input class="field" name="urutan" type="number" value="<?= h($edit['urutan']??'0') ?>"></div><button class="btn btn-coffee w-full">Simpan kategori</button><?php if($edit):?><a href="<?= h(BASE_URL) ?>/admin/categories.php" class="block text-center text-sm underline">Batal edit</a><?php endif;?></form></section><section class="card p-5"><h2 class="font-serif text-2xl">Daftar kategori</h2><div class="table-wrap mt-4"><table class="admin-table"><thead><tr><th>Urutan</th><th>Nama</th><th>Jumlah menu</th><th>Aksi</th></tr></thead><tbody><?php foreach($cats as $c):?><tr><td><?= (int)$c['urutan'] ?></td><td class="font-semibold"><?= h($c['nama']) ?></td><td><?= (int)$c['total_menu'] ?></td><td><div class="flex gap-3"><a class="underline text-xs" href="?edit=<?= (int)$c['id'] ?>">Edit</a><form method="post" onsubmit="return confirm('Hapus kategori ini? kategori yang masih dipakai menu tidak bisa dihapus.')"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><button class="underline text-xs text-red-700">Hapus</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require __DIR__.'/../includes/admin-footer.php'; ?>
